function freshDB(){return {records:initialRecords(),audit:[{id:1,created:now(),type:'Workspace siap',detail:'8 permohonan fiktif dimuat. Semua kontrol memakai mock lokal.',ref:'SYSTEM'}],settings:{face:85,live:90,attempts:3},counter:1048};}
let db;
try{db=JSON.parse(localStorage.getItem(storageKey));if(!db || !Array.isArray(db.records) || !Array.isArray(db.audit) || !db.settings) db=freshDB();}catch{db=freshDB();}
let page='dashboard',session=null,progress=0,running=false,timer=null,toastTimer;
let cameraStream=null,cameraTarget=null,cameraToken=0,exportURL=null;
let queueFilter='all',queueQuery='',auditQuery='';
function save(){try{localStorage.setItem(storageKey,JSON.stringify(db));}catch{toast('Penyimpanan browser tidak tersedia. Data bertahan selama tab ini terbuka.');}}
function audit(type,detail,ref='SYSTEM'){db.audit.unshift({id:Date.now()+Math.random(),created:now(),type,detail,ref});save();}
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function badge(status){const [label,color]=statuses[status] || ['—','gray'];return `<span class="badge ${color}"><span class="swatch" style="background:currentColor"></span>${label}</span>`;}
function dateTime(value){return new Intl.DateTimeFormat('id-ID',{dateStyle:'medium',timeStyle:'short',timeZone:'Asia/Jakarta'}).format(new Date(value));}
function timeOnly(value){return new Intl.DateTimeFormat('id-ID',{hour:'2-digit',minute:'2-digit',timeZone:'Asia/Jakarta'}).format(new Date(value));}
function initials(name){return name.split(' ').slice(0,2).map(s=>s[0]).join('').toUpperCase();}
function masked(nik){return '•••• •••• •••• '+String(nik).slice(-4);}
function head(title,subtitle,action='',eyebrow='IDENTITY VERIFICATION'){return `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${subtitle}</p></div>${action}</div>`;}
function rows(records){return records.map(r=>`<tr><td><div class="person-cell"><span class="person-avatar">${escapeHTML(initials(r.name))}</span><div><strong>${escapeHTML(r.name)}</strong><small>${escapeHTML(masked(r.nik))}</small></div></div></td><td><strong class="session-id">${escapeHTML(r.id)}</strong><small>${dateTime(r.created)} WIB</small></td><td>${badge(r.status)}</td><td>${r.duration.toFixed(1)} detik<small>Simulasi</small></td><td><button class="row-action" data-detail="${escapeHTML(r.id)}" aria-label="Detail ${escapeHTML(r.name)}">Detail ↗</button></td></tr>`).join('') || '<tr><td colspan="5" class="empty">Tidak ada permohonan yang sesuai.</td></tr>';}
const table = records => `<div class="table-wrap"><table><thead><tr><th>PEMOHON</th><th>ID VERIFIKASI</th><th>STATUS</th><th>WAKTU PROSES</th><th>AKSI</th></tr></thead><tbody>${rows(records)}</tbody></table></div>`;
function updateNav(){for(const b of $$('nav button[data-page]')){const p=b.dataset.page;const count=db.records.filter(r=>['manual','scheduled'].includes(r.status)).length;b.innerHTML=`${icon(p)}<span>${pageNames[p]}</span>${p==='queue'?`<span class="count">${count}</span>`:''}`;b.classList.toggle('active',p===page);if(p===page)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');}$('#crumb').textContent=pageNames[page];}
function render(){updateNav();const views={dashboard:dashboard,verify:verification,queue:queuePage,audit:auditPage,modules:modulesPage};$('#app').innerHTML=`<div class="screen-enter">${views[page]()}</div>`;}
function navigate(p){if(!pageNames[p])p='dashboard';page=p;if(p==='verify'&&!session)newSession();render();window.scrollTo(0,0);}
function newSession(){session={id:`SES-${crypto.randomUUID().slice(0,8).toUpperCase()}`,step:0,scenario:'pass',document:false,image:null,selfie:null,holding:null,kycReady:false,challenge:0,attempt:1,name:'Alya Pratama',nik:'0000000000000001',birth:'1995-04-12',address:'Jl. Contoh No. 12, Kota Demo',consent:false,result:null,started:Date.now(),startedAt:now(),nonce:crypto.randomUUID(),nonceUsed:false};progress=0;}
function dashboard(){const total=db.records.length;const passed=db.records.filter(r=>['pass','approved'].includes(r.status)).length;const manual=db.records.filter(r=>['manual','scheduled'].includes(r.status)).length;const avg=(db.records.reduce((a,r)=>a+r.duration,0)/total).toFixed(1);const other=total-passed-manual;const percent=Math.round(passed/total*100);return `${head('Ringkasan verifikasi','Pantau verifikasi identitas dan tindak lanjut dalam satu workspace.',`<button class="button primary" data-new>${icon('plus')} Verifikasi baru</button>`)}
<div class="hero"><div class="hero-copy"><div class="hero-label"><span></span> VERIFIKASI IDENTITAS, LEBIH TERARAH</div><h2>Satu alur. Identitas lebih pasti.</h2><p>Dari pembacaan KTP hingga keputusan verifikasi. Bantu pemohon melanjutkan dengan panduan yang jelas di setiap langkah.</p><div class="hero-bottom"><button class="button light" data-new>Coba alur pemohon ${icon('arrow')}</button><small>± 1 menit • tanpa akun • data fiktif</small></div></div><div class="hero-art" aria-hidden="true"><div class="orbit three"></div><div class="orbit two"></div><div class="orbit"></div><span class="mini-tag">IDENTITY VERIFIED</span><div class="shield">${icon('check')}</div><span class="floating-check">✓</span></div></div>
<div class="stats"><div class="stat"><div class="stat-top">Total permohonan ${icon('file')}</div><div class="stat-number">${total}</div><div class="stat-meta"><span class="trend">${db.records.filter(r=>r.source==='demo').length} sesi baru</span> dataset demo lokal</div></div><div class="stat"><div class="stat-top">Lulus verifikasi ${icon('verify')}</div><div class="stat-number">${percent}<span style="font-size:18px">%</span></div><div class="stat-meta"><span class="trend">${passed} pemohon</span> otomatis & manual</div></div><div class="stat"><div class="stat-top">Antrean manual ${icon('queue')}</div><div class="stat-number">${manual.toString().padStart(2,'0')}</div><div class="stat-meta"><span class="trend orange">Perlu tindak lanjut</span></div></div><div class="stat"><div class="stat-top">Rata-rata proses ${icon('clock')}</div><div class="stat-number">${avg}<span style="font-size:16px;margin-left:4px">dtk</span></div><div class="stat-meta">Durasi ilustratif, bukan benchmark</div></div></div>
<div class="grid-two"><section class="panel"><div class="panel-head"><div><h2>Alur verifikasi otomatis</h2><p>Capture KYC, pemeriksaan identitas, dan tindak lanjut.</p></div><span class="new-tag">MOCK PIPELINE</span></div><div class="panel-body flow-list">${[['Dokumen & OCR KTP','Kualitas gambar dan ekstraksi data identitas','file','PaddleOCR'],['Selfie & liveness','Panduan gerakan dan deteksi anti-spoof','face','MiniFASNet'],['Foto diri bersama KTP','Keterlihatan wajah dan dokumen yang dipegang','face','KYC capture'],['Pencocokan wajah','Verifikasi 1:1 terhadap foto referensi','face','SFace'],['Integritas & identitas','Deepfake, injection, dan adapter Dukcapil','verify','Mock adapter'],['Keputusan & tindak lanjut','Lulus, ulang capture, retry, manual, atau keamanan','queue','Rules engine']].map(([title,desc,i,tag],n)=>`<div class="flow-item"><span class="flow-number">${n+1}</span><div class="flow-info"><h3>${title}</h3><p>${desc}</p></div><span class="badge gray">${tag}</span></div>`).join('')}</div></section>
<section class="panel"><div class="panel-head"><div><h2>Distribusi keputusan</h2><p>Seluruh permohonan di browser ini.</p></div></div><div class="panel-body"><div class="donut-wrap"><div class="donut" style="background:conic-gradient(#36745b 0 ${passed/total*100}%,#dcc098 ${passed/total*100}% ${(passed+manual)/total*100}%,#cad2c2 ${(passed+manual)/total*100}% 100%)"><div class="donut-label"><strong>${total}</strong><small>permohonan</small></div></div><div class="legend">${[['Lulus',passed,'#36745b'],['Manual',manual,'#dcc098'],['Lainnya',other,'#cad2c2']].map(([label,n,color])=>`<div class="legend-row"><span class="swatch" style="background:${color}"></span>${label}<strong>${n.toString().padStart(2,'0')}</strong></div>`).join('')}</div></div><div class="callout">${icon('info')} Antrean manual hanya untuk identitas yang belum pasti. Masalah capture dan gangguan teknis memiliki alur perbaikan tersendiri.</div></div></section></div>
<section class="panel table-panel"><div class="panel-head"><div><h2>Permohonan terbaru</h2><p>Data fiktif untuk menjelajahi alur petugas.</p></div><button class="button link" data-page="queue">Lihat antrean ${icon('arrow')}</button></div>${table(db.records.slice(0,4))}<div class="table-bottom">Menampilkan ${Math.min(4,total)} dari ${total} permohonan <span style="float:right">Semua waktu dalam WIB</span></div></section>`;}
function verification(){if(!session)newSession();const steps=['Dokumen','Data identitas','Selfie','Foto + KTP','Hasil'];return `${head('Verifikasi identitas','Alur pemohon untuk pengajuan informasi debitur.',`<span class="badge gray">${icon('info')} SIMULASI LOKAL</span>`,'APPLICANT EXPERIENCE')}<div class="verification-layout"><section class="panel verification-panel"><div class="stepper" aria-label="Tahapan verifikasi">${steps.map((s,i)=>`<div class="step ${session.step===i?'current':session.step>i?'done':''}" ${session.step===i?'aria-current="step"':''}><b>${session.step>i?'✓':i+1}</b>${s}</div>`).join('')}</div><div class="step-content">${[documentStep,identityStep,selfieStep,kycStep,resultStep][session.step]()}</div></section><aside class="verification-aside"><section class="panel session-card"><h3>Informasi sesi</h3><div class="session-row"><span>ID sesi</span><strong class="session-id">${session.id}</strong></div><div class="session-row"><span>Status</span><strong>${running?'Memproses':session.result?'Selesai':'Dalam proses'}</strong></div><div class="session-row"><span>Percobaan</span><strong>${session.attempt} / ${db.settings.attempts}</strong></div><div class="session-row"><span>Data identitas</span><strong>Contoh fiktif</strong></div><div class="state-note">Sesi ilustratif berlaku 15 menit. Nonce lokal sekali pakai dan batas percobaan berlaku pada alur demo ini.</div></section><section class="panel scenario-card"><h3>Skenario demo</h3><p>Pilih hasil yang ingin Anda eksplorasi sebelum memulai pemrosesan.</p>${Object.entries(scenarioNames).map(([key,name])=>`<label class="scenario"><input type="radio" name="scenario" value="${key}" ${session.scenario===key?'checked':''} ${running||session.result?'disabled':''}><span>${name}<small>${{pass:'Semua kontrol wajib terpenuhi',capture:'Foto KTP kurang jelas',technical:'Layanan identitas tidak merespons',manual:'Skor kecocokan wajah rendah',attack:'Sinyal spoof, deepfake, atau injection'}[key]}</small></span></label>`).join('')}<div class="simulation-note">Pilihan ini menghasilkan skor mock. Foto yang diunggah hanya ditampilkan, tanpa OCR atau analisis biometrik.</div></section></aside></div>`;}
function ktp(){return `<div class="ktp"><div class="ktp-header">REPUBLIK DEMO<br>KARTU IDENTITAS CONTOH</div><div class="ktp-body"><div class="ktp-data"><strong>NIK ${escapeHTML(session.nik)}</strong><br>Nama: ${escapeHTML(session.name)}<br>Lahir: 12 APRIL 1995<br>Alamat: Jl. Contoh No. 12<br>Kota: KOTA DEMO</div><div class="ktp-portrait">${portrait}</div></div><div class="ktp-watermark">FIKTIF • BUKAN DOKUMEN RESMI</div></div>`;}
function documentStep(){return `<h2>Mulai dari dokumen Anda</h2><p class="step-description">Gunakan KTP contoh atau unggah gambar untuk mencoba tampilan capture. Pastikan dokumen terlihat utuh dan tidak silau.</p><div class="upload-zone">${icon('upload')}<h3>${session.document?'Dokumen siap ditinjau':'Tambahkan foto KTP'}</h3><p>JPG, PNG, atau WebP • maksimal 5 MB</p><div class="upload-buttons"><button class="button" data-camera="ktp">${icon('face')} Buka kamera</button><button class="button" data-upload="ktp">${icon('upload')} Pilih gambar</button><button class="button ${session.document?'':'primary'}" data-sample>Gunakan KTP contoh</button></div><input type="file" id="ktp-file" accept="image/jpeg,image/png,image/webp" aria-label="Unggah gambar KTP">${session.document?(session.image?`<img class="image-preview" src="${session.image}" alt="Pratinjau gambar yang diunggah">`:ktp()):''}</div><p class="text-error" id="step-error" role="alert"></p><label class="scenario"><input type="checkbox" id="consent" ${session.consent?'checked':''}><span>Saya memahami bahwa ini demo dengan hasil simulasi.<small>Gunakan gambar contoh. Gambar unggahan disimpan sementara dalam memori tab.</small></span></label><div class="form-actions"><span class="micro">${icon('verify')} Preview gambar diproses di browser.</span><button class="button primary" data-next-doc ${session.document&&session.consent?'':'disabled'}>Lanjutkan ${icon('arrow')}</button></div>`;}
function identityStep(){return `<h2>Tinjau data identitas</h2><p class="step-description">Contoh keluaran OCR terstruktur. Anda bisa mengoreksi data sebelum melanjutkan ke capture wajah.</p><div class="validation-note">${icon('check')} Data contoh berhasil dimuat • ekstraksi OCR disimulasikan. Unggahan tidak dibaca oleh model.</div><form id="identity-form"><div class="form-grid"><div class="field wide"><label for="nik">NIK contoh</label><input id="nik" name="nik" inputmode="numeric" pattern="[0-9]{16}" minlength="16" maxlength="16" value="${escapeHTML(session.nik)}" required><small>16 digit fiktif. NIK tidak divalidasi terhadap sumber resmi.</small></div><div class="field"><label for="name">Nama lengkap</label><input id="name" name="name" maxlength="80" value="${escapeHTML(session.name)}" required></div><div class="field"><label for="birth">Tanggal lahir</label><input id="birth" name="birth" type="date" max="${new Date().toLocaleDateString('en-CA')}" value="${escapeHTML(session.birth)}" required></div><div class="field wide"><label for="address">Alamat contoh</label><input id="address" name="address" maxlength="180" value="${escapeHTML(session.address)}" required></div></div><p class="text-error" id="step-error" role="alert"></p><div class="form-actions"><button type="button" class="button" data-back>Kembali</button><button class="button primary" type="submit">Data sudah sesuai ${icon('arrow')}</button></div></form>`;}
function selfieStep(){return `<h2>Selfie & pemeriksaan liveness</h2><p class="step-description">Coba tiga tantangan gerakan melalui tombol simulasi. Ilustrasi wajah digunakan tanpa mengakses kamera Anda.</p><div class="capture"><span class="capture-tag">CAPTURE SIMULATOR</span><span class="capture-corner">${session.challenge}/3 tantangan</span><div class="face-oval ${session.challenge===3?'complete':''}">${session.selfie?`<img src="${session.selfie}" alt="Pratinjau selfie" style="width:100%;height:100%;object-fit:cover;border-radius:50%">`:portrait}</div><span class="capture-caption">${['Posisikan wajah di dalam bingkai','Tantangan berikutnya: menoleh ke kiri','Tantangan berikutnya: tersenyum','Semua tantangan demo selesai ✓'][session.challenge]}</span></div><div class="challenge-list">${['Kedipkan mata','Menoleh kiri','Tersenyum'].map((n,i)=>`<div class="challenge ${session.challenge>i?'complete':session.challenge===i?'active':''}">${session.challenge>i?'✓':i+1} ${n}</div>`).join('')}</div><div class="upload-buttons">${session.challenge<3?`<button class="button" data-challenge>Simulasikan ${['kedipan','menoleh','senyuman'][session.challenge]} ${icon('arrow')}</button>`:`<span class="badge green">✓ Capture siap diproses</span>`}<button class="button" data-camera="selfie">Buka kamera</button><button class="button" data-upload="selfie">Pilih foto preview</button><input type="file" id="selfie-file" accept="image/jpeg,image/png,image/webp" aria-label="Unggah foto selfie preview" hidden></div><div class="state-note">Gerakan tidak dianalisis. MiniFASNet, SFace, dan deteksi deepfake akan mengembalikan skor contoh sesuai skenario.</div><p class="text-error" id="step-error" role="alert"></p><div class="form-actions"><button class="button" data-back>Kembali</button><button class="button primary" data-next-kyc ${session.challenge===3?'':'disabled'}>${icon('arrow')} Lanjutkan foto + KTP</button></div>`;}

function holdingIllustration(){return `<svg viewBox="0 0 480 290" role="img" aria-label="Ilustrasi pemohon memegang KTP contoh di bawah wajah" class="holding-illustration"><rect width="480" height="290" fill="#eef1e8"/><circle cx="240" cy="136" r="105" fill="#e0e7d6"/><path d="M131 290v-33c0-71 218-71 218 0v33" fill="#587763"/><path d="M220 163v46q20 23 40 0v-46" fill="#cda27b"/><ellipse cx="240" cy="108" rx="52" ry="66" fill="#e7ba94"/><path d="M189 110c-17-75 31-89 51-86 53-2 69 43 51 87l-13-48c-25 13-50 4-69-4z" fill="#344b3b"/><path d="M216 115h4m42 0h4" stroke="#52644a" stroke-width="5" stroke-linecap="round"/><path d="M225 143q15 11 30 0" stroke="#b98060" stroke-width="3" fill="none"/><rect x="176" y="213" width="135" height="74" rx="5" fill="#c2dbe0" stroke="#aecacf"/><text x="186" y="225" font-size="6" fill="#46616a" font-weight="700">KARTU IDENTITAS CONTOH</text><path d="M187 239h61m-61 9h43m-43 9h59m-59 9h35" stroke="#6d8c91" stroke-width="3"/><rect x="263" y="235" width="34" height="39" rx="2" fill="#8ca7ab"/><circle cx="280" cy="245" r="8" fill="#d6b291"/><path d="M268 273c0-17 24-17 24 0" fill="#4f6d5b"/><path d="M145 287c9-31 19-49 31-47 14-6 26 9 23 16l-4 31" fill="#d9ad85"/><path d="M335 287c-9-31-19-49-31-47-14-6-26 9-23 16l4 31" fill="#d9ad85"/><path d="M183 76v-15h16M281 61h16v15M297 171v15h-16M199 186h-16v-15" fill="none" stroke="#69945e" stroke-width="2"/><path d="M170 224v-16h16M303 208h16v16M319 274v14h-16M186 288h-16v-14" fill="none" stroke="#69945e" stroke-width="2"/></svg>`;}
function kycStep(){if(running)return processingStep();return `<h2>Foto diri sambil memegang KTP</h2><p class="step-description">Tampilkan wajah dan KTP fisik dalam satu foto. Pegang KTP di bawah dagu agar wajah serta seluruh bagian dokumen terlihat jelas.</p><div class="kyc-preview"><span class="capture-tag">KYC · FOTO BERSAMA KTP</span>${session.holding?`<img class="holding-image" src="${session.holding}" alt="Pratinjau foto diri sambil memegang KTP">`:holdingIllustration()}<span class="kyc-example-label">${session.holding?'PREVIEW UNGGAHAN · BELUM DIANALISIS':'ILUSTRASI CONTOH · DATA FIKTIF'}</span></div><div class="kyc-guidance"><div><span>01</span><strong>Wajah terlihat utuh</strong><small>KTP tidak menutupi wajah.</small></div><div><span>02</span><strong>KTP terlihat jelas</strong><small>Empat sudut dan teks terbaca.</small></div><div><span>03</span><strong>Dokumen yang sama</strong><small>Gunakan KTP yang diunggah.</small></div></div><div class="upload-buttons"><button class="button" data-camera="holding">${icon('face')} Ambil foto dengan kamera</button><button class="button" data-upload="holding">${icon('upload')} Pilih foto bersama KTP</button><button class="button ${session.kycReady?'':'primary'}" data-kyc-sample>Gunakan contoh foto + KTP</button><input type="file" id="holding-file" accept="image/jpeg,image/png,image/webp" aria-label="Unggah foto diri memegang KTP" hidden></div>${session.kycReady?'<div class="validation-note" style="margin-top:18px">✓ Foto KYC siap untuk pipeline simulasi.</div>':''}<div class="state-note">Foto bersama KTP mendukung pemeriksaan penguasaan dokumen fisik. Demo ini belum mendeteksi wajah atau KTP pada unggahan dan belum membuktikan kepemilikan sah secara otomatis. Foto di atas tidak disimpan ke localStorage.</div><p class="text-error" id="step-error" role="alert"></p><div class="form-actions"><button class="button" data-back>Kembali</button><button class="button primary" data-process ${session.kycReady?'':'disabled'}>${icon('verify')} Jalankan verifikasi</button></div>`;}

const processLabels=[['Foto diri bersama KTP','Wajah, dokumen di tangan, dan kesesuaian KTP • mock','face'],['Pembacaan KTP','Ekstraksi data identitas • PaddleOCR mock','file'],['Liveness & pencocokan wajah','Anti-spoof dan verifikasi 1:1 • MiniFASNet / SFace mock','face'],['Integritas media & sesi','Deepfake, injection, dan nonce sekali pakai • mock','verify'],['Pemeriksaan sumber identitas','Kecocokan data • adapter Dukcapil mock','link'],['Menentukan tindak lanjut','Evaluasi kontrol wajib dan aturan demo','queue']];
function processingStep(){return `<h2>Memeriksa identitas…</h2><p class="step-description">Pipeline simulasi sedang berjalan. Hasil akan diarahkan ke tindak lanjut yang sesuai.</p>${processLabels.map(([name,desc,i],n)=>`<div class="progress-row ${progress>n?'complete':progress===n?'processing':''}"><span class="progress-icon">${progress>n?'✓':progress===n?'<span class="spinner"></span>':icon(i)}</span><div class="flow-info"><h3>${name}</h3><p>${desc}</p></div><span class="badge ${progress>n?'green':'gray'}">${progress>n?'Selesai':progress===n?'Memproses':'Menunggu'}</span></div>`).join('')}<div class="state-note">Skenario: ${scenarioNames[session.scenario]} • semua pemeriksaan merupakan simulasi.</div>`;}
const outcomeText={
 scheduled:['Pemeriksaan sudah dijadwalkan','Petugas telah menjadwalkan pemeriksaan manual untuk permohonan fiktif ini. Lihat detail antrean untuk waktu reservasi.','◷','blue'],
 approved:['Disetujui oleh petugas','Pemeriksaan manual dalam demo selesai. Keputusan ini hanya berlaku pada data fiktif lokal.','✓','green'],
 rejected:['Belum dapat disetujui','Petugas telah mencatat keputusan dan alasan dalam audit demo. Lihat detail untuk catatan pemeriksaan.','!','orange'],
 pass:['Identitas terverifikasi','Seluruh kontrol wajib dalam simulasi terpenuhi. Pemohon dapat melanjutkan pengajuan iDeb.','✓','green'],
 capture:['Mari perbaiki foto KTP','Dokumen contoh memiliki skor kualitas rendah. Ulangi capture dengan gambar yang lebih terang, tajam, dan utuh.','↻','orange'],
 technical:['Layanan belum merespons','Adapter identitas simulasi mengalami timeout. Coba retry terukur tanpa masuk ke antrean helpdesk.','↻','blue'],
 manual:['Perlu pemeriksaan petugas','Skor pencocokan wajah belum memenuhi ambang demo. Permohonan masuk antrean untuk pemeriksaan manual terjadwal.','◷','orange'],
 attack:['Perlu tinjauan keamanan','Skenario mock menemukan indikasi spoof, deepfake, atau injection. Permohonan ditandai untuk penanganan keamanan.','!','red']
};
function resultStep(){if(!session.result)return '';const r=session.result;const [title,desc,symbol,color]=outcomeText[r.status];return `<div class="result-banner"><div class="result-symbol ${color}">${symbol}</div><h2>${title}</h2><p>${desc}</p>${badge(r.status)}</div><div class="score-grid"><div class="score"><small>OCR confidence</small><strong>${r.scores.ocr.toFixed(1)}%</strong></div><div class="score"><small>Face similarity</small><strong>${r.scores.face.toFixed(1)}%</strong></div><div class="score"><small>Liveness score</small><strong>${r.scores.live.toFixed(1)}%</strong></div></div>${resultControls(r)}<div class="state-note">${escapeHTML(r.id)} • ${dateTime(r.created)} WIB<br>Skor di atas adalah data simulasi, bukan hasil analisis foto. ${r.status==='pass'?'Pengajuan iDeb asli tidak dikirim dari demo ini.':''}</div><div class="form-actions"><button class="button" data-export-result>${icon('download')} Unduh hasil</button><div class="buttons">${['capture','technical'].includes(r.status)?`<button class="button primary" data-retry ${session.attempt>=db.settings.attempts?'disabled':''}>${r.status==='capture'?'Ulangi capture':'Retry verifikasi'} (${session.attempt}/${db.settings.attempts})</button>`:['manual','scheduled'].includes(r.status)?'<button class="button primary" data-page="queue">Lihat antrean manual</button>':['attack','rejected'].includes(r.status)?`<button class="button primary" data-detail="${r.id}">Lihat detail keputusan</button>`:'<button class="button primary" data-demo-next>Lanjutkan pengajuan demo</button>'}</div></div><div style="margin-top:20px"><button class="button link" data-new>Mulai sesi baru ${icon('arrow')}</button></div>`;}
function resultControls(r){const result=[['KYC · wajah & KTP dalam satu foto',r.status==='capture'?'Perlu capture ulang':'Kontrol mock terpenuhi',r.status==='capture'?'orange':'green'],['KYC · KTP sesuai dokumen unggahan','Cocok pada mock','green'],['Kualitas & data KTP',r.status==='capture'?'Perlu capture ulang':'Lulus mock',r.status==='capture'?'orange':'green'],['Liveness / PAD',r.status==='attack'?'Indikasi spoof':'Lulus mock',r.status==='attack'?'red':'green'],['Pencocokan wajah 1:1',r.scores.face>=(r.rules?.face ?? 85)?'Lulus mock':'Di bawah ambang',r.scores.face>=(r.rules?.face ?? 85)?'green':'orange'],['Deepfake risk',`${r.scores.deepfake.toFixed(1)}% · mock`,r.status==='attack'?'red':'green'],['Integritas jalur capture',r.status==='attack'?'Indikasi injection':'Kontrol mock terpenuhi',r.status==='attack'?'red':'green'],['Sumber identitas',r.status==='technical'?'Timeout mock':'Cocok pada mock',r.status==='technical'?'blue':'green']];return `<div class="result-controls">${result.map(([name,value,color])=>`<div class="result-control"><span>${name}</span><span class="badge ${color}">${value}</span></div>`).join('')}</div>`;}
function queuePage(){const records=db.records.filter(r=>['manual','scheduled'].includes(r.status));return `${head('Antrean pemeriksaan manual','Tindak lanjuti identitas yang belum pasti dengan pemeriksaan terjadwal.',`<button class="button" data-export-queue>${icon('download')} Ekspor antrean</button>`,'OPERATOR WORKSPACE')}<div class="stats" style="grid-template-columns:repeat(3,1fr)"><div class="stat"><div class="stat-top">Menunggu petugas ${icon('queue')}</div><div class="stat-number">${records.filter(r=>r.status==='manual').length.toString().padStart(2,'0')}</div><div class="stat-meta">Belum memiliki jadwal</div></div><div class="stat"><div class="stat-top">Sudah terjadwal ${icon('clock')}</div><div class="stat-number">${records.filter(r=>r.status==='scheduled').length.toString().padStart(2,'0')}</div><div class="stat-meta">Reservasi pemeriksaan manual</div></div><div class="stat"><div class="stat-top">Selesai diperiksa ${icon('check')}</div><div class="stat-number">${db.records.filter(r=>['approved','rejected'].includes(r.status)).length.toString().padStart(2,'0')}</div><div class="stat-meta">Keputusan manual pada demo</div></div></div><section class="panel"><div class="panel-head"><div><h2>Daftar tindak lanjut</h2><p>Gunakan detail permohonan untuk menjadwalkan dan mencatat keputusan.</p></div><span class="badge orange">${records.length} permohonan</span></div><div class="filters"><input id="queue-search" aria-label="Cari pemohon" placeholder="Cari nama atau ID verifikasi…" value="${escapeHTML(queueQuery)}"><select id="queue-filter" aria-label="Filter status antrean"><option value="all" ${queueFilter==='all'?'selected':''}>Semua status</option><option value="manual" ${queueFilter==='manual'?'selected':''}>Menunggu petugas</option><option value="scheduled" ${queueFilter==='scheduled'?'selected':''}>Terjadwal</option></select></div><div id="queue-table">${queueTable()}</div><div class="table-bottom">Kegagalan capture dan gangguan teknis ditangani lewat alur perbaikan pemohon.</div></section>`;}
function queueTable(){return table(db.records.filter(r=>['manual','scheduled'].includes(r.status)&&(queueFilter==='all'||r.status===queueFilter)&&`${r.name} ${r.id}`.toLowerCase().includes(queueQuery.toLowerCase())));}
function auditItems(){const items=db.audit.filter(e=>`${e.type} ${e.detail} ${e.ref}`.toLowerCase().includes(auditQuery.toLowerCase()));return items.map(e=>`<div class="audit-event"><div class="event-icon">${icon('audit')}</div><div class="event-content"><h3>${escapeHTML(e.type)} <span class="badge gray" style="margin-left:8px">${escapeHTML(e.ref)}</span></h3><p>${escapeHTML(e.detail)}</p></div><time>${dateTime(e.created)} WIB</time></div>`).join('') || '<div class="empty">Tidak ada aktivitas yang sesuai.</div>';}
function auditPage(){return `${head('Jejak aktivitas','Catatan lokal untuk sesi verifikasi, reservasi, dan keputusan petugas.',`<button class="button" data-export-audit>${icon('download')} Ekspor audit</button>`,'AUDIT WORKSPACE')}<div class="callout" style="margin-bottom:22px">${icon('info')} Audit demo tersimpan di localStorage browser ini dan dapat diubah atau dihapus. Untuk produksi diperlukan audit server yang tahan manipulasi.</div><section class="panel"><div class="filters"><input id="audit-search" aria-label="Cari aktivitas" placeholder="Cari aktivitas atau ID…" value="${escapeHTML(auditQuery)}"><span class="micro">${db.audit.length} aktivitas tercatat</span></div><div id="audit-list">${auditItems()}</div></section>`;}
function modulesPage(){return `${head('Modul & konfigurasi','Arsitektur awal dari percakapan GPT, ditampilkan sebagai adapter mock.',`<span class="badge orange">7 adapter simulasi</span>`,'DEMO CONFIGURATION')}<div class="callout">${icon('info')} Model open source di bawah adalah kandidat dari referensi GPT. Kode demo ini belum mengunduh atau menjalankan model, dan belum memiliki backend FastAPI.</div><div class="module-grid">${moduleList.map(([i,name,model,desc])=>`<section class="panel module-card">${icon(i)}<h3>${name}</h3><p>${desc}</p><div class="module-meta"><span>${model}</span><span class="badge gray">MOCK</span></div></section>`).join('')}</div><section class="panel config-panel"><h2>Aturan keputusan demo</h2><p>Ambang berikut memengaruhi sesi baru. Nilainya hanya ilustratif dan bukan rekomendasi untuk produksi.</p><form id="settings-form"><div class="settings-grid"><div class="field"><label for="face-threshold">Minimum face similarity (%)</label><input id="face-threshold" name="face" type="number" min="50" max="99" step="1" value="${db.settings.face}" required><small>Skor mock di bawah ambang diarahkan ke manual.</small></div><div class="field"><label for="live-threshold">Minimum liveness score (%)</label><input id="live-threshold" name="live" type="number" min="50" max="99" step="1" value="${db.settings.live}" required><small>Skor mock rendah diarahkan ke tinjauan keamanan.</small></div><div class="field"><label for="max-attempts">Maksimum percobaan per sesi</label><input id="max-attempts" name="attempts" type="number" min="1" max="5" step="1" value="${db.settings.attempts}" required><small>Retry dan capture ulang berbagi batas yang sama.</small></div></div><div class="form-actions"><span class="micro">Perubahan disimpan di browser ini.</span><button class="button primary" type="submit">Simpan konfigurasi</button></div></form></section><section class="panel config-panel"><h2>Dataset demo</h2><p>Kembalikan delapan permohonan contoh beserta konfigurasi awal. Anda dapat mengunduh audit terlebih dahulu.</p><button class="button danger" data-reset>Reset data demo</button></section>`;}
function modal(title,content){cleanupExport();stopCamera();const d=$('#modal');d.innerHTML=`<div class="modal-head"><h2 id="modal-title">${title}</h2><button class="modal-close" data-close aria-label="Tutup dialog">×</button></div><div class="modal-content">${content}</div>`;d.setAttribute('aria-labelledby','modal-title');if(!d.open)d.showModal();}
function detail(id){const r=db.records.find(r=>r.id===id);if(!r)return;const manual=['manual','scheduled'].includes(r.status);modal('Detail permohonan',`<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:20px"><div><h2>${escapeHTML(r.name)}</h2><p style="margin:5px 0 0;font-size:10px">${escapeHTML(r.id)} • pemohon fiktif</p></div>${badge(r.status)}</div><div class="detail-grid"><div class="detail-box">NIK contoh<strong>${escapeHTML(masked(r.nik))}</strong></div><div class="detail-box">Tanggal permohonan<strong>${dateTime(r.created)} WIB</strong></div><div class="detail-box">Face similarity<strong>${r.scores.face.toFixed(1)}% · mock</strong></div><div class="detail-box">Liveness score<strong>${r.scores.live.toFixed(1)}% · mock</strong></div></div><div class="modal-controls">${resultControls(r)}</div>${r.status==='attack'?'<p class="modal-notice">Indikasi serangan berasal dari skenario simulasi. Pada implementasi produksi, arahkan kasus ini ke proses keamanan terpisah.</p>':''}${r.schedule?`<p class="validation-note">Reservasi: ${dateTime(new Date(r.schedule+'+07:00'))} WIB</p>`:''}${r.note?`<p>Catatan petugas: ${escapeHTML(r.note)}</p>`:''}${manual?`<form id="manual-form" data-id="${r.id}"><div class="field"><label for="operator-note">Catatan pemeriksaan petugas</label><input id="operator-note" name="note" placeholder="Tuliskan alasan keputusan (min. 5 karakter)" minlength="5" maxlength="250" required></div><p class="modal-notice">Keputusan ini hanya mengubah data fiktif di demo lokal.</p><div class="buttons"><button type="submit" class="button primary" name="decision" value="approved">Setujui demo</button><button type="submit" class="button danger" name="decision" value="rejected">Tidak setujui demo</button></div></form><form id="schedule-form" data-id="${r.id}" class="schedule"><div class="field"><label for="schedule-at">Jadwalkan pemeriksaan (WIB)</label><input id="schedule-at" type="datetime-local" name="schedule" required></div><button type="submit" class="button">Simpan jadwal</button></form><p class="text-error" id="modal-error" role="alert"></p>`:''}<div class="form-actions"><span class="micro">Skor & sumber identitas: mock</span><button class="button" data-close>Tutup</button></div>`);}

function stopCamera(){cameraToken++;if(cameraStream){cameraStream.getTracks().forEach(t=>t.stop());cameraStream=null;}cameraTarget=null;}
async function openCamera(kind){
 modal(kind==='holding'?'Ambil foto diri memegang KTP':kind==='ktp'?'Ambil foto KTP':'Ambil foto selfie', `<p>${kind==='holding'?'Pegang KTP di bawah dagu. Wajah dan seluruh dokumen harus terlihat dalam satu bingkai.':kind==='ktp'?'Letakkan dokumen di area yang terang dan tampilkan seluruh bagian kartu.':'Posisikan wajah di tengah bingkai.'}</p><div class="camera-preview"><video id="camera-video" autoplay playsinline muted aria-label="Pratinjau kamera lokal"></video><div class="camera-overlay ${kind==='holding'?'holding':kind==='ktp'?'document':''}" aria-hidden="true"><span class="camera-face-guide"></span>${kind==='holding'||kind==='ktp'?'<span class="camera-card-guide">KTP</span>':''}</div></div><p class="state-note" id="camera-status">Menunggu izin kamera dari browser…</p><div class="form-actions"><button class="button" data-close>Batal</button><button class="button primary" data-take-photo disabled>Ambil foto</button></div>`);
 cameraTarget=kind;const captureSession=session;const requestToken=cameraToken;
 try{
  if(!navigator.mediaDevices?.getUserMedia)throw new Error('unsupported');
  const stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:kind==='ktp'?'environment':'user'},width:{ideal:1280},height:{ideal:720}},audio:false});
  if(!$('#modal').open||cameraTarget!==kind||session!==captureSession||cameraToken!==requestToken){stream.getTracks().forEach(t=>t.stop());return;}
  cameraStream=stream;const video=$('#camera-video');video.srcObject=stream;await video.play();
  video.onloadeddata=()=>{if($('[data-take-photo]'))$('[data-take-photo]').disabled=false;};
  if(video.readyState>=2)$('[data-take-photo]').disabled=false;
  $('#camera-status').textContent='Kamera aktif. Foto hanya menjadi preview lokal; pemeriksaan AI tetap disimulasikan.';
 }catch(error){if(cameraToken!==requestToken)return;if($('#camera-status'))$('#camera-status').textContent=error.name==='NotAllowedError'?'Izin kamera tidak diberikan. Tutup dialog lalu gunakan unggahan atau foto contoh.':error.name==='NotFoundError'?'Kamera tidak ditemukan. Gunakan unggahan atau foto contoh.':'Kamera tidak tersedia. Gunakan browser pada localhost dan pilih unggahan atau foto contoh.';stopCamera();}
}
function takePhoto(){const video=$('#camera-video');if(!cameraStream||!video||video.readyState<2)return;const canvas=document.createElement('canvas');canvas.width=video.videoWidth;canvas.height=video.videoHeight;canvas.getContext('2d').drawImage(video,0,0);const data=canvas.toDataURL('image/jpeg',.85);const kind=cameraTarget;stopCamera();if(kind==='ktp'){session.image=data;session.document=true;}else if(kind==='holding'){session.holding=data;session.kycReady=true;}else session.selfie=data;$('#modal').close();render();toast('Foto diambil untuk preview lokal. Analisis tetap simulasi.');}

function cleanupExport(){if(exportURL){URL.revokeObjectURL(exportURL);exportURL=null;}}
function download(filename,body,type){const blob=new Blob([body],{type});const url=URL.createObjectURL(blob);modal('Ekspor siap',`<p>File <strong>${escapeHTML(filename)}</strong> siap diunduh. Jika browser membatasi unduhan, salin isi file di bawah.</p><div class="field"><label for="export-content">Isi file demo</label><textarea id="export-content" readonly rows="10">${escapeHTML(body)}</textarea></div><div class="form-actions"><button class="button" data-copy-export>Salin isi file</button><a class="button primary" href="${url}" download="${escapeHTML(filename)}">Unduh file</a><button class="button" data-close>Tutup</button></div>`);exportURL=url;const a=document.createElement('a');a.href=url;a.download=filename;a.hidden=true;document.body.append(a);a.click();a.remove();toast('File demo berhasil disiapkan.');}
function csvCell(v){let s=String(v??'');if(/^[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';}
function csvDownload(filename,headers,rows){download(filename,'\uFEFF'+[headers,...rows].map(r=>r.map(csvCell).join(',')).join('\r\n'),'text/csv;charset=utf-8');}
function startProcess(){if(running||!session||session.challenge!==3||!session.kycReady)return;if(Date.now()-session.started>15*60*1000){$('#step-error').textContent='Sesi demo sudah kedaluwarsa. Mulai sesi baru untuk melanjutkan.';return;}if(session.nonceUsed){$('#step-error').textContent='Nonce sesi telah dipakai. Mulai sesi baru atau gunakan retry.';return;}session.nonceUsed=true;session.rules={...db.settings};running=true;progress=0;audit('Verifikasi dimulai',`Skenario ${scenarioNames[session.scenario]}. Percobaan ${session.attempt}. Nonce mock dikonsumsi.`,session.id);render();const processingSession=session;function tick(){if(session!==processingSession)return;progress++;if(progress>=processLabels.length){finishProcess();return;}if(page==='verify')render();timer=setTimeout(tick,650);}timer=setTimeout(tick,650);}
function finishProcess(){running=false;timer=null;const scores={pass:{ocr:98.6,face:97.4,live:99.1,deepfake:2.1},capture:{ocr:61.2,face:86.1,live:94.3,deepfake:3.2},technical:{ocr:98.6,face:97.4,live:99.1,deepfake:2.1},manual:{ocr:96.2,face:72.4,live:97.8,deepfake:3.2},attack:{ocr:97.4,face:94.1,live:24.5,deepfake:86.3}}[session.scenario];let status=session.scenario;if(!['technical','capture','attack'].includes(status)){status=scores.live<session.rules.live?'attack':scores.face<session.rules.face?'manual':'pass';}db.counter++;const record={id:`VRF-${db.counter}`,name:session.name,nik:session.nik,status,scenario:session.scenario,created:now(),duration:3.9,scores:{...scores},rules:{...session.rules},attempt:session.attempt,session:session.id,source:'demo'};db.records.unshift(record);session.result=record;session.step=4;audit('Verifikasi selesai',`Keputusan: ${statuses[status][0]}. Semua skor disimulasikan.`,record.id);save();if(page==='verify')render();else{render();toast('Verifikasi simulasi selesai. Hasil tersedia di Verifikasi baru.');}}
function retry(){if(running||session.attempt>=db.settings.attempts)return;const previous=session.result;session.attempt++;session.result=null;session.nonce=crypto.randomUUID();session.nonceUsed=false;session.step=previous.status==='capture'?0:3;if(previous.status==='capture'){session.document=false;session.challenge=0;session.image=null;session.kycReady=false;session.holding=null;}audit('Percobaan ulang',`Percobaan ${session.attempt}. Nonce mock baru dibuat. Skenario dapat diubah sebelum memproses.`,session.id);render();toast('Pilih skenario Lulus otomatis untuk mencoba pemulihan.');}
function freshSession(){stopCamera();if($('#modal').open)$('#modal').close();if(running){clearTimeout(timer);audit('Sesi dibatalkan','Sesi simulasi dibatalkan untuk memulai sesi baru.',session.id);running=false;}newSession();location.hash='verify';navigate('verify');}
function help(){modal('Tentang iDeb Verify',`<p>Demo lokal ini menerjemahkan percakapan <a href="https://chatgpt.com/share/6acba866-18b0-83ec-9287-0fb9eabb5b18" target="_blank" rel="noopener noreferrer">Rancang Alur Verifikasi Otomatis</a> menjadi pengalaman pemohon dan petugas.</p><div class="detail-grid"><div class="detail-box">Interaksi yang tersedia<strong>Capture KTP, selfie, foto bersama KTP, koreksi data, skenario, retry, antrean, reservasi, audit & ekspor.</strong></div><div class="detail-box">Penyimpanan<strong>localStorage browser. Gambar berada sementara dalam memori tab.</strong></div></div><p style="margin-top:18px">OCR, liveness, face matching, deepfake, injection, dan Dukcapil memakai mock. Skor berasal dari skenario yang Anda pilih; belum ada model AI, API resmi, atau pengajuan iDeb yang dikirim.</p><p>Gunakan data fiktif. Halaman dapat berjalan offline setelah server lokal aktif. Semua waktu ditampilkan dalam WIB.</p><div class="form-actions"><span class="micro">Prototipe independen, bukan layanan resmi OJK.</span><button class="button primary" data-close>Mulai menjelajah</button></div>`);}
function fileUpload(file,kind){if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)){toast('Gunakan gambar JPG, PNG, atau WebP.');return;}if(file.size>5*1024*1024){toast('Ukuran gambar melebihi 5 MB.');return;}const targetSession=session;const reader=new FileReader();reader.onload=()=>{if(session!==targetSession)return;const image=new Image();image.onload=()=>{if(session!==targetSession)return;if(kind==='ktp'){session.image=reader.result;session.document=true;}else {if(kind==='holding'){session.holding=reader.result;session.kycReady=true;}else session.selfie=reader.result;}if(page==='verify')render();toast('Preview gambar dimuat. Hasil analisis tetap simulasi.');};image.onerror=()=>toast('Gambar tidak dapat dibaca. Gunakan gambar lain.');image.src=reader.result;};reader.onerror=()=>toast('File tidak dapat dibaca.');reader.readAsDataURL(file);}
document.addEventListener('click',event=>{const b=event.target.closest('button');if(!b||b.disabled)return;
 if(b.dataset.page){location.hash=b.dataset.page;navigate(b.dataset.page);}
 else if(b.hasAttribute('data-new'))freshSession();
 else if(b.hasAttribute('data-close'))$('#modal').close();
 else if(b.hasAttribute('data-copy-export')){const field=$('#export-content');if(navigator.clipboard?.writeText){navigator.clipboard.writeText(field.value).then(()=>toast('Isi file disalin.')).catch(()=>{field.select();toast('Pilih dan salin isi file secara manual.');});}else{field.select();toast('Pilih dan salin isi file secara manual.');}}
 else if(b.dataset.detail)detail(b.dataset.detail);
 else if(b.hasAttribute('data-sample')){session.document=true;session.image=null;render();}
 else if(b.dataset.camera)openCamera(b.dataset.camera);
 else if(b.hasAttribute('data-take-photo'))takePhoto();
 else if(b.dataset.upload)$(b.dataset.upload==='ktp'?'#ktp-file':b.dataset.upload==='holding'?'#holding-file':'#selfie-file').click();
 else if(b.hasAttribute('data-next-doc')){if(!session.document||!session.consent)return;session.step=1;render();}
 else if(b.hasAttribute('data-back')){session.step=Math.max(0,session.step-1);render();}
 else if(b.hasAttribute('data-challenge')){session.challenge=Math.min(3,session.challenge+1);render();}
 else if(b.hasAttribute('data-next-kyc')){session.step=3;render();}
 else if(b.hasAttribute('data-kyc-sample')){session.kycReady=true;session.holding=null;render();}
 else if(b.hasAttribute('data-process'))startProcess();
 else if(b.hasAttribute('data-retry'))retry();
 else if(b.hasAttribute('data-export-result'))download(`${session.result.id}-mock.json`,JSON.stringify({demo:true,disclaimer:'Semua skor dan hasil identitas disimulasikan. Tidak untuk verifikasi nyata.',...session.result},null,2),'application/json');
 else if(b.hasAttribute('data-export-queue'))csvDownload('antrean-demo.csv',['ID','Nama fiktif','Status','Jadwal WIB','Face mock','Liveness mock'],db.records.filter(r=>['manual','scheduled'].includes(r.status)).map(r=>[r.id,r.name,statuses[r.status][0],r.schedule||'',r.scores.face,r.scores.live]));
 else if(b.hasAttribute('data-export-audit'))csvDownload('audit-demo.csv',['Waktu UTC','Aktivitas','Referensi','Catatan'],db.audit.map(e=>[e.created,e.type,e.ref,e.detail]));
 else if(b.hasAttribute('data-demo-next'))modal('Pengajuan demo siap dilanjutkan',`<p>Verifikasi simulasi ${escapeHTML(session.result.id)} selesai. Pada aplikasi sebenarnya, hasil backend akan diteruskan ke alur pengajuan iDebKu.</p><div class="validation-note">✓ Selesai — tidak ada permohonan yang dikirim ke OJK.</div><div class="buttons"><button class="button primary" data-close>Selesai</button><button class="button" data-new>Mulai sesi lain</button></div>`);
 else if(b.hasAttribute('data-reset'))modal('Reset dataset demo',`<p>Delapan permohonan fiktif awal akan dimuat ulang. Sesi baru, reservasi, keputusan, audit, dan konfigurasi demo di browser ini akan dihapus.</p><div class="buttons"><button class="button" data-close>Batal</button><button class="button danger" data-confirm-reset>Reset data lokal</button></div>`);
 else if(b.hasAttribute('data-confirm-reset')){clearTimeout(timer);running=false;db=freshDB();session=null;save();$('#modal').close();navigate('dashboard');location.hash='dashboard';toast('Dataset demo dikembalikan ke kondisi awal.');}
});
document.addEventListener('change',event=>{const t=event.target;
 if(t.name==='scenario'&&session&&!running&&!session.result){session.scenario=t.value;}
 if(t.id==='consent'){session.consent=t.checked;$('[data-next-doc]').disabled=!session.document||!session.consent;}
 if(t.id==='ktp-file')fileUpload(t.files[0],'ktp');
 if(t.id==='selfie-file')fileUpload(t.files[0],'selfie');
 if(t.id==='holding-file')fileUpload(t.files[0],'holding');
 if(t.id==='queue-filter'){queueFilter=t.value;$('#queue-table').innerHTML=queueTable();}
});
document.addEventListener('input',event=>{const t=event.target;if(t.id==='queue-search'){queueQuery=t.value;$('#queue-table').innerHTML=queueTable();}if(t.id==='audit-search'){auditQuery=t.value;$('#audit-list').innerHTML=auditItems();}});
document.addEventListener('submit',event=>{const form=event.target;event.preventDefault();if(!form.checkValidity()){form.reportValidity();return;}
 if(form.id==='identity-form'){const data=Object.fromEntries(new FormData(form));if(!/^\d{16}$/.test(data.nik)||data.name.trim().length<2){$('#step-error').textContent='Masukkan NIK 16 digit dan nama minimal 2 karakter.';return;}Object.assign(session,{nik:data.nik,name:data.name.trim(),birth:data.birth,address:data.address.trim()});session.step=2;render();}
 if(form.id==='settings-form'){const data=Object.fromEntries(new FormData(form));db.settings={face:Number(data.face),live:Number(data.live),attempts:Number(data.attempts)};audit('Konfigurasi diubah',`Face ${db.settings.face}%, liveness ${db.settings.live}%, batas ${db.settings.attempts} percobaan.`);toast('Konfigurasi demo tersimpan.');}
 if(form.id==='manual-form'){const r=db.records.find(r=>r.id===form.dataset.id);const note=String(new FormData(form).get('note')).trim();if(note.length<5){$('#modal-error').textContent='Catatan pemeriksaan minimal 5 karakter.';return;}const decision=event.submitter?.value;if(!r||!['manual','scheduled'].includes(r.status)||!['approved','rejected'].includes(decision))return;r.status=decision;r.note=note;r.reviewedAt=now();audit('Keputusan petugas',`${statuses[decision][0]}: ${note}`,r.id);$('#modal').close();render();toast('Keputusan untuk pemohon fiktif tersimpan.');}
 if(form.id==='schedule-form'){const r=db.records.find(r=>r.id===form.dataset.id);const v=new FormData(form).get('schedule');if(new Date(v+'+07:00').getTime()<=Date.now()){ $('#modal-error').textContent='Pilih jadwal di waktu mendatang (WIB).';return;}if(!r||!['manual','scheduled'].includes(r.status))return;r.schedule=v;r.scheduleZone='Asia/Jakarta';r.status='scheduled';audit('Reservasi manual',`Pemeriksaan dijadwalkan ${dateTime(new Date(v+'+07:00'))} WIB.`,r.id);render();detail(r.id);toast('Jadwal pemeriksaan demo tersimpan.');}
});
$('#help').addEventListener('click',help);
window.addEventListener('hashchange',()=>{const p=location.hash.slice(1);if(p!==page)navigate(p);});
$('#modal').addEventListener('close',()=>{stopCamera();cleanupExport();});
window.addEventListener('beforeunload',()=>{stopCamera();if(timer)clearTimeout(timer);});
save();navigate(location.hash.slice(1)||'dashboard');
